import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Platform overview","description":"","frontmatter":{},"headers":[],"relativePath":"handl/overview.md","filePath":"vendored/handl/overview.md"}`),a={name:`handl/overview.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="platform-overview" tabindex="-1">Platform overview <a class="header-anchor" href="#platform-overview" aria-label="Permalink to “Platform overview”">​</a></h1><p>handl is a <strong>composable language platform</strong>. A single <code>Plugin</code> trait unifies libraries, targets, operations, and rules. A <code>Host</code> loads plugins from one or more kits, resolves their dependencies, runs their <code>contribute</code> methods to a fixed point, and then executes capabilities on demand.</p><p>This page covers the published platform layers. The language surface — syntax, standard library, and the <code>hnl</code> toolchain — is not yet released and is not documented here.</p><h2 id="core-concepts" tabindex="-1">Core concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to “Core concepts”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>Host                       # empty composer</span></span>
<span class="line"><span>  └── PluginRegistry       # every loaded thing is a Plugin</span></span>
<span class="line"><span>        ├── Library        # registers more plugins</span></span>
<span class="line"><span>        ├── Target         # contributes backends and target options</span></span>
<span class="line"><span>        ├── Operation      # accepts rules for a cross-cutting concern</span></span>
<span class="line"><span>        ├── Rule           # contributes Behavior&lt;Op&gt; to an Operation</span></span>
<span class="line"><span>        └── Options        # resolves option values from schemas</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Concept</th><th>What it is</th></tr></thead><tbody><tr><td><code>Plugin</code></td><td>The universal, object-safe trait. Every loaded component implements it.</td></tr><tr><td><code>RuleAcceptor&lt;Rule&gt;</code></td><td>A sub-trait for plugins that accept contributions.</td></tr><tr><td><code>Operation</code></td><td>A marker type for a cross-cutting concern such as <code>Format</code>, <code>Lint</code>, <code>Eval</code>, <code>Cli</code>, or <code>Lsp</code>.</td></tr><tr><td><code>Behavior&lt;Op&gt;</code></td><td>A rule that a plugin contributes to a specific <code>Operation</code> for a specific <code>AstNode</code> kind.</td></tr><tr><td><code>Kit</code></td><td>A curated manifest of plugins and default option values.</td></tr><tr><td><code>HostConfig</code></td><td>In-memory description of kits, direct plugins, excludes, and option overrides.</td></tr><tr><td><code>HostApplier</code></td><td>Reads <code>.handl.toml</code>, CLI flags, and env and applies them to a <code>Host</code>.</td></tr></tbody></table><h2 id="what-a-plugin-can-be" tabindex="-1">What a plugin can be <a class="header-anchor" href="#what-a-plugin-can-be" aria-label="Permalink to “What a plugin can be”">​</a></h2><ul><li><strong>Library plugin</strong> — registers more plugins, such as <code>StringTypePlugin</code> or <code>ConcatPlugin</code>.</li><li><strong>Target plugin</strong> — adds a runtime backend, such as <code>native</code>, <code>wasm</code>, or <code>js-native</code>.</li><li><strong>Operation plugin</strong> — accepts rules for <code>Format</code>, <code>Lint</code>, <code>Parser</code>, <code>Eval</code>, <code>Cli</code>, <code>Lsp</code>, and so on.</li><li><strong>Rule plugin</strong> — contributes <code>Behavior</code> rules to existing operations, such as a formatter rule for a new AST node kind.</li><li><strong>Options plugin</strong> — resolves option values from contributed schemas.</li></ul><h2 id="host-loading-flow" tabindex="-1">Host loading flow <a class="header-anchor" href="#host-loading-flow" aria-label="Permalink to “Host loading flow”">​</a></h2><ol><li>Create a <code>Host</code>.</li><li>Use a <code>HostApplier</code> to read <code>.handl.toml</code> and apply a <code>HostConfig</code>.</li><li>Call <code>Host::load</code> to resolve dependencies and run <code>contribute</code> to a fixed point.</li><li>During <code>contribute</code>, plugins register more plugins, contribute rules, and define options.</li><li>Call <code>Host::execute</code> to run a capability.</li></ol><h2 id="the-object-arrow-kernel" tabindex="-1">The object/arrow kernel <a class="header-anchor" href="#the-object-arrow-kernel" aria-label="Permalink to “The object/arrow kernel”">​</a></h2><p>The language core is a single semantic world: <code>Obj : sym()</code>, <code>Type : Obj := sym()</code>, and the arrow <code>A ~&gt; B</code> as the only computational primitive. The VM primitives <code>sym()</code> / <code>sym(A)</code> create fresh nominal identity (with an optional parent), and the same <code>sym</code> parent graph powers runtime <code>instanceof</code>, static subtyping <code>&lt;:</code>, and polymorphism — no separate subtype, interface, trait, or impl systems. Types, grades, proofs, algebras, and capabilities are ordinary objects; generics, dependent types, and refinements ride on one dimension form, <code>f&lt;...&gt;</code>; composition is <code>&gt;&gt;&gt;</code> (do-blocks lower to it); state is explicit data (<code>State ~&gt; (State, Result)</code>), so programs are serializable arrow graphs with no closures or mutable bindings.</p><p>For the full kernel design, read <a href="https://github.com/handl-lang/host/blob/project/adrs/0106-object-arrow-kernel.md" target="_blank" rel="noreferrer">ADR-0106: The object/arrow kernel</a>.</p><p>For the full platform design, read <a href="https://github.com/handl-lang/host/blob/project/adrs/archived/0002-handl-platform-composable-host.md" target="_blank" rel="noreferrer">ADR-0002: Single Plugin Model</a>. For hands-on instructions, see the <a href="./tutorials/build-a-host.html">Build a host tutorial</a>.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};